parameters.jsCode:
const data = $input.first().json.body;

const candidateId    = data.candidateId;
const firstName      = data.candidateFirstName || 'Candidat';
const lastName       = data.candidateLastName  || '';
const candidateEmail = data.candidateEmail || '';
const jobTitle       = data.jobOfferTitle || 'le poste';

return [{ json: {
  candidateId, firstName, lastName, candidateEmail, jobTitle,
  selectedAt: new Date().toISOString()
} }];

const data = $input.first().json.body;

const interviewId     = data.interviewId;
const candidateFirst  = data.candidateFirstName || 'Candidat';
const candidateLast   = data.candidateLastName  || '';
const candidateEmail  = data.candidateEmail;
const jobTitle        = data.jobOfferTitle || 'le poste';
const interviewDate   = data.scheduledDate;
const durationMinutes = data.durationMinutes || 30;

const typeLabels = {
  PHONE:     '📞 Entretien téléphonique',
  VIDEO:     '💻 Entretien vidéo (visioconférence)',
  ONSITE:    '🏢 Entretien sur site',
  TECHNICAL: '⚙️ Test technique',
};
const interviewType    = typeLabels[data.interviewType] || data.interviewType || 'Entretien';
const isVideo           = data.interviewType === 'VIDEO';
const interviewerName  = data.interviewerName  || 'Notre équipe';
const interviewerEmail = data.interviewerEmail || null;
const notes            = data.notes || '';

const startIso = interviewDate ? new Date(interviewDate).toISOString() : null;
const endIso   = interviewDate ? new Date(new Date(interviewDate).getTime() + durationMinutes * 60000).toISOString() : null;

const dateFormatted = interviewDate
  ? new Date(interviewDate).toLocaleString('fr-FR', { dateStyle: 'full', timeStyle: 'short' })
  : 'À confirmer';

return [{ json: {
  interviewId, candidateFirst, candidateLast, candidateEmail,
  jobTitle, interviewType, isVideo, interviewerName, interviewerEmail, interviewDate,
  startIso, endIso, dateFormatted, notes,
  scheduledAt: new Date().toISOString()
} }];

